.container {
  display: flex; /* превращаем в flex-контейнер */
}

.item {
  background: #bbdefb;
  padding: 20px;
  margin: 5px;
}

.row {
  display: flex;
  flex-direction: row;          /* слева направо (по умолчанию) */
}

.row-reverse {
  display: flex;
  flex-direction: row-reverse;  /* справа налево */
}

.column {
  display: flex;
  flex-direction: column;       /* сверху вниз */
}

.column-reverse {
  display: flex;
  flex-direction: column-reverse; /* снизу вверх */
}

.container {
  display: flex;
  flex-wrap: wrap; /* разрешаем перенос */
}

.container {
  display: flex;
  gap: 16px; /* 16px между каждыми элементами */
}

/* Разные gap для строк и колонок */
.container {
  display: flex;
  flex-wrap: wrap;
  row-gap: 16px;    /* расстояние между строками */
  column-gap: 24px;  /* расстояние между колонками */
}

.menu {
  display: flex;
  gap: 20px;
  padding: 16px;
  background: #f5f5f5;
}

.menu a {
  text-decoration: none;
  color: #333;
  padding: 8px 16px;
  border-radius: 4px;
}

.menu a:hover {
  background: #e0e0e0;
}

.product-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
}

.product-card {
  flex: 1 1 200px; /* растягивается, сжимается, мин. 200px */
  padding: 20px;
  background: white;
  border: 1px solid #ddd;
  border-radius: 8px;
}
